def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or replacing
            if len(s_in) > len(s_out):
                # Deleting at position i
                return (s_in[i], "", i)
            elif len(s_in) < len(s_out):
                # Inserting at position i
                return ("", s_out[i], i)
            else:
                # Replacing at position i
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[len(s_out)], "", len(s_out))
    elif len(s_in) < len(s_out):
        return ("", s_out[len(s_in)], len(s_in))
    else:
        return ("", "", -1)  # No difference

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a change."""
    # This is a simplified version - in practice this would be more sophisticated
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    if old_sub == "" and new_sub != "":
        # Insertion case
        return [(new_sub, new_sub)]
    elif old_sub != "" and new_sub == "":
        # Deletion case  
        return [(old_sub, "")]
    else:
        # Replacement case
        return [(old_sub, new_sub)]

